function displayMenu() {
  for (let category in sections) {
    const section = document.createElement('div');
    section.innerHTML = `
      <div class="section-title ${category}">${category.charAt(0).toUpperCase() + category.slice(1)}</div>
      <div class="food-grid" id="${category}-grid"></div>
    `;
    menu.appendChild(section);

    const grid = section.querySelector(".food-grid");

    sections[category].forEach(item => {
      const card = document.createElement("div");
      card.className = "food-item";
      card.innerHTML = `
        <img src="${item.img}" alt="${item.name}">
        <div class="food-info">
          <h3>${item.name}</h3>
          <p>₹${item.price}</p>
          <button onclick="addToCart('${item.name}', ${item.price})">Add to Cart</button>
        </div>
      `;
      grid.appendChild(card);
    });
  }
}

function addToCart(name, price) {
  cart.push({ name, price });
  updateCart();
}

function updateCart() {
  cartItems.innerHTML = '';
  let total = 0;
  cart.forEach(item => {
    const li = document.createElement('li');
    li.textContent = `${item.name} - ₹${item.price}`;
    cartItems.appendChild(li);
    total += item.price;
  });

  let discount = 0;
  if (total > 500) {
    discount = total * 0.10;
    discountText.textContent = "🎉 10% off applied!";
  } else {
    discountText.textContent = "";
  }

  let finalTotal = total - discount;

  if (finalTotal > 1000) {
    bonusDessert.style.display = "block";
    if (!cart.some(item => item.name === "Free Dessert")) {
      cart.push({ name: "Free Dessert", price: 0 });
      updateCart(); return;
    }
  } else {
    bonusDessert.style.display = "none";
  }

  totalText.textContent = `Total: ₹${finalTotal}`;
}

function placeOrder() {
  trackingSection.classList.remove("hidden");
  let steps = [
    "Order Confirmed ✅",
    "Food is being prepared 🍳",
    "Delivery partner on the way 🛵",
    "Delivered! 🍽️"
  ];
  const partner = deliveryPartners[Math.floor(Math.random() * deliveryPartners.length)];
  deliveryPartner.textContent = `Delivery Partner: ${partner}`;

  let i = 0;
  trackingStatus.textContent = steps[i];
  let interval = setInterval(() => {
    i++;
    if (i < steps.length) {
      trackingStatus.textContent = steps[i];
    } else {
      clearInterval(interval);
    }
  }, 5000);
}

displayMenu();
